from pathlib import Path
import datetime,hashlib,json,math,os,statistics,subprocess,time
root=Path(__file__).resolve().parent
r=root/'timing'
r.mkdir(exist_ok=False)
meta=json.loads((root/'timing-preparation.json').read_text())
models={'0.6b':Path.home()/'.cache/huggingface/hub/models--Qwen--Qwen3-0.6B-GGUF/snapshots/23749fefcc72300e3a2ad315e1317431b06b590a/Qwen3-0.6B-Q8_0.gguf','8b':Path.home()/'.lmstudio/models/Qwen/Qwen3-8B-GGUF/Qwen3-8B-Q8_0.gguf'}
expected={'0.6b':'9465e63a22add5354d9bb4b99e90117043c7124007664907259bd16d043bb031','8b':'408b955510e196121c1c375201744783b5c9a43c7956d73fc78df54c66e883d6'}
exes={k:meta['artifacts'][k]['path'] for k in ['control','candidate','mx']}
tokens=meta['artifacts']['tokens']['path']
def now():return datetime.datetime.now(datetime.timezone.utc).isoformat()
def sha(p):
 with Path(p).open('rb') as f:return hashlib.file_digest(f,'sha256').hexdigest()
def contention():
 cmd="Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.ProcessName -match '^(llmx|llama|candidate-compare|control-compare|q16-|model-witness|cl$|cmake$|ninja$|g\\+\\+$)' } | Select-Object Id,ProcessName | ConvertTo-Json -Compress"
 return subprocess.check_output(['powershell','-NoProfile','-Command',cmd],text=True).strip()
def arm_order(pair):
 arms=['control','candidate','mx']
 if pair<0:return arms
 if (pair//3)%2:arms.reverse()
 shift=pair%3
 return arms[shift:]+arms[:shift]
state={'status':'preparing','started':now(),'pid':os.getpid(),'models':{},'rows':[],'within_arm_hashes':{}}
def save():(r/'results.json').write_text(json.dumps(state,indent=2)+'\n')
assert not (r/'results.json').exists(),'fresh results required'
save()
try:
 assert sha(root/'source-manifest.json')==meta['source_manifest_sha256']
 for name,digests in json.loads((root/'source-manifest.json').read_text()).items():
  assert sha(root/name)==digests['sha256'],name
 state['runner_sha256']=sha(Path(__file__))
 state['preparation_sha256']=sha(root/'timing-preparation.json')
 for k,p in models.items():
  digest=sha(p);assert digest==expected[k]
  state['models'][k]={'path':str(p),'sha256':digest,'bytes':p.stat().st_size}
 for k,a in meta['artifacts'].items():assert sha(a['path'])==a['sha256'],k
 state['status']='running';save()
 for pair in range(-1,9):
  for model in (list(models) if pair%2==0 else list(reversed(models))):
   for arm in arm_order(pair):
    active=contention();assert not active,'Competing process before invocation: '+active
    name=f'{model}-pair{pair}-{arm}'
    command=[exes[arm],str(models[model]),tokens,'--threads','6']
    row={'name':name,'pair':pair,'model':model,'arm':arm,'command':command,'status':'running','started':now()}
    state['rows'].append(row);save();print('START',name,flush=True)
    with (r/(name+'.stdout')).open('wb') as stdout,(r/(name+'.stderr')).open('wb') as stderr:
     child=subprocess.Popen(command,stdout=stdout,stderr=stderr)
     row['pid']=child.pid;save()
     try:rc=child.wait(timeout=300)
     except subprocess.TimeoutExpired:
      child.kill();child.wait();row['status']='timeout';save();raise
    row.update(returncode=rc,completed=now());assert rc==0,(name,rc)
    active=contention();assert not active,'Competing process after invocation: '+active
    records=[json.loads(line) for line in (r/(name+'.stdout')).read_bytes().splitlines() if line.startswith(b'{')]
    assert len(records)==2 and [x['run'] for x in records]==[0,1]
    for record in records:
     assert record['threads']==6 and record['pp_tokens']==215 and record['tg_tokens']==32
     assert all(math.isfinite(record[k]) and record[k]>0 for k in ['pp_ms','tg_ms'])
     assert math.isfinite(record['logit_sum'])
    assert records[0]['top1']==records[1]['top1'] and records[0]['logit_sum']==records[1]['logit_sum']
    hashes=[line.split()[1].decode() for line in (r/(name+'.stderr')).read_bytes().splitlines() if line.startswith(b'vector_hash ')]
    key=model+'/llmx'
    if arm in ('control','candidate'):
     assert len(hashes)==2 and hashes[0]==hashes[1]
     if key in state['within_arm_hashes']:assert hashes[1]==state['within_arm_hashes'][key]
     state['within_arm_hashes'][key]=hashes[1]
    row.update(status='pass',records=records,vector_hashes=hashes);save();print('PASS',name,flush=True)
 summary=[]
 for model in models:
  for phase,count in [('pp',215),('tg',32)]:
   item={'model':model,'phase':phase}
   for arm in exes:
    samples=[1000*count/x['records'][1][phase+'_ms'] for x in state['rows'] if x['model']==model and x['arm']==arm and x['pair']>=0]
    assert len(samples)==9
    item[arm]={'samples':samples,'mean':statistics.mean(samples),'median':statistics.median(samples),'min':min(samples),'max':max(samples)}
   for a,b in [('candidate','control'),('candidate','mx'),('control','mx')]:
    ratios=[x/y for x,y in zip(item[a]['samples'],item[b]['samples'])]
    item[a+'_vs_'+b]={'paired_ratios':ratios,'paired_wins':sum(x>=1 for x in ratios),
      'mean_gap_percent':100*(item[a]['mean']/item[b]['mean']-1),
      'median_gap_percent':100*(item[a]['median']/item[b]['median']-1)}
   summary.append(item)
 state.update(status='pass',completed=now(),summary=summary);save()
 (r/'summary.json').write_text(json.dumps(summary,indent=2)+'\n')
 print(json.dumps(summary,indent=2),flush=True)
except BaseException as e:
 state.update(status='failed',completed=now(),error=repr(e));save();raise
